      "* Main logic to regulate aquarium temperature.",
      "BEGIN.",
      "    DISPLAY \"Enter current aquarium temperature: \"",
      "    ACCEPT CURRENT-TEMP",
      "    PERFORM CHECK-TEMPERATURE",
      "    DISPLAY \"Adjustment needed: \", ADJUSTMENT",
      "    STOP RUN.",
      "CHECK-TEMPERATURE.",
