      "PROCEDURE DIVISION.",
      "BEGIN.",
      "    OPEN INPUT item-catalog loan-records",
      "        OUTPUT overdue-notices",
      "    PERFORM PROCESS-LOANS UNTIL EOF",
      "    CLOSE item-catalog loan-records overdue-notices",
